static constexpr std::size_t kGeneratedCodebookLayerCount =
    sizeof(kGeneratedCodebookLayers) / sizeof(kGeneratedCodebookLayers[0]);

inline const GeneratedCodebookLayerView* findGeneratedCodebookLayer(const char* name) {
    for (std::size_t i = 0; i < kGeneratedCodebookLayerCount; ++i) {
        if (std::strcmp(kGeneratedCodebookLayers[i].name, name) == 0) {
            return &kGeneratedCodebookLayers[i];
        }
    }
    return nullptr;
}

inline std::size_t getGeneratedCodebookSize(const GeneratedCodebookLayerView& view) {
    return static_cast<std::size_t>(1u) << view.bits_per_cb;
}

inline std::size_t getGeneratedWeightIdxCount(const GeneratedCodebookLayerView& view) {
    return view.output_size * view.n_words_row;
}

inline const uint32_t* getGeneratedCodebookWeightIdx(const GeneratedCodebookLayerView* view, std::size_t learner = 0) {
    if (view == nullptr) {
        return nullptr;
    }
    if (view->same_seq || view->weight_idx_by_learner == nullptr) {
        return view->weight_idx;
    }
    if (learner >= view->n_learners) {
        return nullptr;
    }
    return view->weight_idx_by_learner + learner * getGeneratedWeightIdxCount(*view);
}

inline const uint32_t* getGeneratedCodebookWeightIdxInterleaved(const GeneratedCodebookLayerView* view) {
    return (view == nullptr) ? nullptr : view->weight_idx_interleaved;
}

inline const int8_t* getGeneratedCodebookInt8(const GeneratedCodebookLayerView* view, std::size_t learner = 0) {
    if (view == nullptr) {
        return nullptr;
    }
    if (view->codebooks_int8 == nullptr) {
        return view->codebook_int8;
    }
    if (learner >= view->n_learners) {
        return nullptr;
    }
    return view->codebooks_int8 + learner * getGeneratedCodebookSize(*view);
}

inline const int8_t* getGeneratedCodebookInt8Interleaved(const GeneratedCodebookLayerView* view) {
    return (view == nullptr) ? nullptr : view->codebook_int8_interleaved;
}

inline const float* getGeneratedCodebookFp32(const GeneratedCodebookLayerView* view, std::size_t learner = 0) {
    if (view == nullptr) {
        return nullptr;
    }
    if (view->codebooks_fp32 == nullptr) {
        return view->codebook_fp32;
    }
    if (learner >= view->n_learners) {
        return nullptr;
    }
    return view->codebooks_fp32 + learner * getGeneratedCodebookSize(*view);
}

inline const float* getGeneratedCodebookFp32Interleaved(const GeneratedCodebookLayerView* view) {
    return (view == nullptr) ? nullptr : view->codebook_fp32_interleaved;
}

inline const float* getGeneratedCodebookBias(const GeneratedCodebookLayerView* view, std::size_t learner = 0) {
    if (view == nullptr) {
        return nullptr;
    }
    if (view->biases == nullptr) {
        return view->bias;
    }
    if (learner >= view->n_learners) {
        return nullptr;
    }
    return view->biases + learner * view->output_size;
}

inline const float* getGeneratedCodebookBiasInterleaved(const GeneratedCodebookLayerView* view) {
    return (view == nullptr) ? nullptr : view->bias_interleaved;
}
